import React, { Component } from "react";
import { ModalManager } from "views/common/plugins/model/Modal";
import FamstackAIChatModal from "./FamstackAIChatModal";

const CHAT_BUTTON_ICON =
  (process.env.PUBLIC_URL || "") + "/assets/images/chatico.jpeg";

class FamstackAIChat extends Component {
  constructor(props) {
    super(props);
    this.state = {
      isModalOpen: false,
    };
  }

  render() {
    return (
      <button
        type="button"
        className="famstack-ai-chat-button"
        onClick={() => {
          if (this.state.isModalOpen) {
            ModalManager.close();
            this.setState({ isModalOpen: false });
          } else {
            ModalManager.open(
              <FamstackAIChatModal
                onRequestClose={() => {
                  ModalManager.close();
                  this.setState({ isModalOpen: false });
                }}
              />
            );
            this.setState({ isModalOpen: true });
          }
        }}
        title="Famstack AI assistant"
        aria-label="Open Famstack AI assistant"
        aria-expanded={this.state.isModalOpen}
      >
        <img
          src={CHAT_BUTTON_ICON}
          alt=""
          width={56}
          height={56}
          decoding="async"
          className="famstack-ai-chat-button__icon"
        />
      </button>
    );
  }
}

export default FamstackAIChat;
