import React, { Component } from "react";
import { QRCodeSVG } from "qrcode.react";
import urlConfig from "url.config";
import { userUtils } from "_helpers";
import envconfig from "env.config";
import "./DeviceRegistrationPopup.css";

class DeviceRegistrationPopup extends Component {
  handleOverlayClick = (e) => {
    // Only close if clicking directly on overlay, not on popup content
    if (e.target === e.currentTarget) {
      this.props.onClose(e);
    }
  }

  handleCloseClick = (e) => {
    e.preventDefault();
    e.stopPropagation();
    this.props.onClose(e);
  }

  render() {
    const registrationUrl = envconfig.BACK_END_API_ENDPOINT + urlConfig.DEVICE_REGISTRATION_URL + "?emailId=" + userUtils.getCurrentUserEmail() + "&userId=" + userUtils.getCurrentUserId();
    
    return (
      <div className="device-registration-popup-overlay" onClick={this.handleOverlayClick}>
        <div className="device-registration-popup" onClick={(e) => e.stopPropagation()}>
          <div className="popup-header">
            <div className="popup-title-wrapper">
              <div className="popup-mobile-app-icon">
                <div className="mobile-app-phone-shape">
                  <div className="popup-qr-code-badge">
                    <i className="fa fa-qrcode"></i>
                  </div>
                  <div className="popup-registration-indicator">REG</div>
                  <i className="fa fa-mobile-alt mobile-app-icon"></i>
                  <div className="home-button"></div>
                </div>
              </div>
              <h3 className="popup-title">
                Mobile App Registration
              </h3>
            </div>
            <button type="button" className="popup-close" onClick={this.handleCloseClick} data-ga-action="device_popup_close" data-ga-category="engagement" data-ga-label="Close">
              <i className="fa fa-times"></i>
            </button>
          </div>
          
          <div className="popup-content">
            <div className="popup-subtitle">
              Connect your mobile device to {envconfig.APP_LABEL} by scanning the QR code below
            </div>

            <div className="popup-registration-content">
              <div className="popup-qr-section">
                <div className="popup-qr-container">
                  <div className="popup-qr-wrapper">
                    <QRCodeSVG
                      value={registrationUrl}
                      title={envconfig.APP_NAME + " Mobile App Registration"}
                      size={160}
                      bgColor={"#ffffff"}
                      fgColor={"#1e293b"}
                      level={"L"}
                      minVersion={7}
                      marginSize={2}
                      imageSettings={{
                        src: envconfig.BACK_END_API_ENDPOINT + "/favicon.ico",
                        x: undefined,
                        y: undefined,
                        height: 16,
                        width: 16,
                        opacity: 1,
                        excavate: true,
                      }}
                    />
                  </div>
                  <div className="popup-qr-label">
                    <i className="fa fa-qrcode mr-2"></i>
                    Scan this QR code
                  </div>
                </div>
              </div>

              <div className="popup-instructions-section">
                <div className="popup-steps-container">
                  <div className="popup-step-item">
                    <div className="popup-step-number">1</div>
                    <div className="popup-step-content">
                      <h5>Download the App</h5>
                      <p>Get {envconfig.APP_NAME} mobile app from your app store</p>
                    </div>
                  </div>
                  <div className="popup-step-item">
                    <div className="popup-step-number">2</div>
                    <div className="popup-step-content">
                      <h5>Open the App</h5>
                      <p>Launch the app on your mobile device</p>
                    </div>
                  </div>
                  <div className="popup-step-item">
                    <div className="popup-step-number">3</div>
                    <div className="popup-step-content">
                      <h5>Scan QR Code</h5>
                      <p>Use the app's scanner to scan this QR code</p>
                    </div>
                  </div>
                  <div className="popup-step-item">
                    <div className="popup-step-number">4</div>
                    <div className="popup-step-content">
                      <h5>Complete Registration</h5>
                      <p>Follow the prompts to complete device registration</p>
                    </div>
                  </div>
                </div>

                <div className="popup-download-section">
                  <h5 className="popup-download-title">
                    <i className="fa fa-download mr-2"></i>
                    Download Mobile App
                  </h5>
                  <div className="popup-app-buttons">
                    <a href="#" className="popup-app-button popup-app-button-apple">
                      <img src="/assets/images/custom/apple-store-btn.png" alt="Download on App Store" />
                    </a>
                    <a href="#" className="popup-app-button popup-app-button-google">
                      <img src="/assets/images/custom/google-store-btn.png" alt="Get it on Google Play" />
                    </a>
                  </div>
                </div>
              </div>
            </div>

            <div className="popup-footer">
              <div className="popup-footer-info">
                <i className="fa fa-info-circle mr-2"></i>
                <span>Make sure your mobile device and computer are on the same network for best results</span>
              </div>
              <a className="d-none" href={registrationUrl}>Registration Link</a>
            </div>
          </div>
        </div>
      </div>
    );
  }
}

export default DeviceRegistrationPopup;
