import React, { PureComponent } from "react";
import dateUtils from "_helpers/date.utils";
import originalMoment from "moment";
import { extendMoment } from "moment-range";

const moment = extendMoment(originalMoment);

const STATUS_OPTIONS = [
  { value: "IN_PROGRESS", label: "In progress" },
  { value: "COMPLETED", label: "Completed" },
];

function parseNoteDateTime(value) {
  if (!value) {
    return moment();
  }
  if (typeof value === "string") {
    const m = dateUtils.convertDateStringToMoment(value);
    return m && m.isValid() ? m : moment();
  }
  if (Array.isArray(value) && value.length >= 5) {
    const [y, mo, d, h, mi] = value;
    return moment({ year: y, month: (mo || 1) - 1, day: d || 1, hour: h || 0, minute: mi || 0 });
  }
  return moment();
}

class NoteEditorModal extends PureComponent {
  constructor(props) {
    super(props);
    this.state = this.emptyForm();
  }

  emptyForm = () => ({
    name: "",
    description: "",
    noteDateTimeLocal: moment().format("YYYY-MM-DDTHH:mm"),
    remindMe: false,
    status: "IN_PROGRESS",
  });

  componentDidUpdate(prevProps) {
    if (this.props.show && !prevProps.show) {
      this.hydrateFromProps();
    }
    if (!this.props.show && prevProps.show) {
      this.setState(this.emptyForm());
    }
  }

  hydrateFromProps = () => {
    const { note } = this.props;
    if (!note) {
      this.setState(this.emptyForm());
      return;
    }
    const dt = parseNoteDateTime(note.noteDateTime);
    this.setState({
      name: note.name || "",
      description: note.description || "",
      noteDateTimeLocal: dt.format("YYYY-MM-DDTHH:mm"),
      remindMe: !!note.remindMe,
      status: note.status === "COMPLETED" ? "COMPLETED" : "IN_PROGRESS",
    });
  };

  onChange = (e) => {
    const { name, type, checked, value } = e.target;
    const v = type === "checkbox" ? checked : value;
    this.setState({ [name]: v });
  };

  buildPayload = () => {
    const { note } = this.props;
    const m = this.state.noteDateTimeLocal ? moment(this.state.noteDateTimeLocal) : moment();
    const noteDateTime = m.isValid()
      ? m.format(dateUtils.SERVER_DATE_FORMAT)
      : moment().format(dateUtils.SERVER_DATE_FORMAT);
    const body = {
      name: (this.state.name || "").trim(),
      description: (this.state.description || "").trim(),
      noteDateTime,
      remindMe: !!this.state.remindMe,
      status: this.state.status,
    };
    if (note && note.id) {
      body.id = note.id;
    }
    return body;
  };

  handleSubmit = (e) => {
    e.preventDefault();
    const payload = this.buildPayload();
    if (!payload.name) {
      return;
    }
    this.props.onSave(payload);
  };

  render() {
    if (!this.props.show) {
      return null;
    }
    const { isSaving, note, onClose } = this.props;
    const isEdit = !!(note && note.id);

    return (
      <div className="modal d-block" tabIndex="-1" role="dialog" style={{ background: "rgba(15,23,42,0.45)" }}>
        <div className="modal-dialog modal-lg" role="document">
          <div className="modal-content">
            <div className="modal-header">
              <h5 className="modal-title">{isEdit ? "Edit note" : "Add note"}</h5>
              <button type="button" className="close" onClick={onClose} aria-label="Close" disabled={isSaving}>
                <span aria-hidden="true">&times;</span>
              </button>
            </div>
            <form onSubmit={this.handleSubmit}>
              <div className="modal-body">
                <div className="form-group">
                  <label className="form-label">Title <span className="text-danger">*</span></label>
                  <input
                    type="text"
                    name="name"
                    className="form-control"
                    value={this.state.name}
                    onChange={this.onChange}
                    maxLength={500}
                    required
                    disabled={isSaving}
                  />
                </div>
                <div className="form-group">
                  <label className="form-label">Description</label>
                  <textarea
                    name="description"
                    className="form-control"
                    rows={4}
                    value={this.state.description}
                    onChange={this.onChange}
                    disabled={isSaving}
                  />
                </div>
                <div className="form-group">
                  <label className="form-label">Date &amp; time</label>
                  <input
                    type="datetime-local"
                    name="noteDateTimeLocal"
                    className="form-control"
                    value={this.state.noteDateTimeLocal}
                    onChange={this.onChange}
                    disabled={isSaving}
                  />
                </div>
                <div className="form-group">
                  <label className="form-label">Status</label>
                  <select
                    name="status"
                    className="form-control custom-select"
                    value={this.state.status}
                    onChange={this.onChange}
                    disabled={isSaving}
                  >
                    {STATUS_OPTIONS.map((o) => (
                      <option key={o.value} value={o.value}>{o.label}</option>
                    ))}
                  </select>
                </div>
                <div className="form-group mb-0">
                  <label className="custom-control custom-checkbox">
                    <input
                      type="checkbox"
                      name="remindMe"
                      className="custom-control-input"
                      checked={this.state.remindMe}
                      onChange={this.onChange}
                      disabled={isSaving}
                    />
                    <span className="custom-control-label">Remind me</span>
                  </label>
                </div>
              </div>
              <div className="modal-footer">
                <button type="button" className="btn btn-secondary" onClick={onClose} disabled={isSaving}>
                  Cancel
                </button>
                <button type="submit" className="btn btn-primary" disabled={isSaving}>
                  {isSaving ? <span className="spinner-border spinner-border-sm mr-1" /> : null}
                  {isEdit ? "Save" : "Create"}
                </button>
              </div>
            </form>
          </div>
        </div>
      </div>
    );
  }
}

export default NoteEditorModal;
