import React, { PureComponent } from "react";
import classNames from "classnames";

class NoteInfoLine extends PureComponent {
  render() {
    const { item: note, permission, formatWhen, onToggleComplete, onEdit, onDelete } = this.props;

    return (
      <tr>
        <td>
          <button
            type="button"
            className="link"
            title={note.status === "COMPLETED" ? "Mark as open" : "Mark complete"}
            disabled={!permission.editEnabled}
            onClick={() => onToggleComplete(note)}
          >
            <i
              className={classNames("pr-1", {
                "fa fa-check-circle text-success": note.status === "COMPLETED",
                "fa fa-circle-o text-muted": note.status !== "COMPLETED",
              })}
            />
          </button>
        </td>
        <td className="w-90 text-muted">{note.id}</td>
        <td className="w-100 d-block">
          <span className="project-due-text colorblue px-1 py-0 mb-0 d-block">{formatWhen(note.noteDateTime)}</span>
        </td>
        <td className="w-250">
          {permission.editEnabled ? (
            <button
              type="button"
              className="link nav-link list-b pl-0 mr-0 pr-0 text-left"
              onClick={() => onEdit(note)}
            >
              <span className="project-name-text d-inline-block text-truncate mt-0 align-middle w-250" title={note.name}>
                {note.name}
              </span>
            </button>
          ) : (
            <span className="project-name-text d-inline-block text-truncate mt-0 align-middle w-250" title={note.name}>
              {note.name}
            </span>
          )}
          {note.description ? (
            <p className="m-0 text-muted text-truncate w-100 small" title={note.description}>
              {note.description}
            </p>
          ) : null}
        </td>
        <td>
          <span
            className={classNames("badge", {
              "badge-success": note.status === "COMPLETED",
              "badge-warning": note.status !== "COMPLETED",
            })}
          >
            {note.status === "COMPLETED" ? "Completed" : "In progress"}
          </span>
        </td>
        <td className="text-center">
          {note.remindMe ? <i className="fe fe-bell text-primary" title="Reminder on" /> : <span className="text-muted">—</span>}
        </td>
        <td className="text-center project-row-actions">
          <button type="button" className="project-row-actions__trigger link" aria-label="Show row actions">
            <span className="project-row-actions__ellipsis" aria-hidden="true">
              ⋯
            </span>
          </button>
          <div className="project-row-actions__panel" role="group" aria-label="Note actions">
            {permission.editEnabled === true && (
              <button type="button" className="link pl-2 project-row-actions__item" title="Edit" onClick={() => onEdit(note)}>
                <i className="fa fa-edit" />
              </button>
            )}
            {permission.removeEnabled === true && (
              <button type="button" className="link pl-2 project-row-actions__item" title="Delete" onClick={() => onDelete(note)}>
                <i className="fa fa-trash" />
              </button>
            )}
          </div>
        </td>
      </tr>
    );
  }
}

export default NoteInfoLine;
