import React, { Component } from "react";
import { commonUtils } from "_helpers";
import dateUtils from "_helpers/date.utils";
import LoadingButton from "views/common/fragments/LoadingButton";

export function getDefaultInvoiceGenerateForm() {
  const lastMonth = dateUtils.getCurrentTime().clone().subtract(1, "month");
  const currentMonth = dateUtils.getCurrentTime().clone();
  const lastDayOfMonth = lastMonth.clone().endOf("month");
  const twentieth = lastMonth.clone().date(20);
  const isoLocal = (m) => m.format("YYYY-MM-DDTHH:mm:ss");
  const monthName = lastMonth.format("MMMM");
  const currentMonthName = currentMonth.format("MMMM");
  return {
    createdBy: commonUtils.getCurrentUserId(),
    userTeamId: commonUtils.getCurrentUserTeamId(),
    name: `${currentMonthName} Invoice`,
    invoiceNumber: `C5${currentMonth.format("YYYYMM")}05`,
    description: `Invoice for the month of ${currentMonthName}`,
    status: "PENDING",
    invoiceDateTime: isoLocal(lastDayOfMonth),
    type: "PER_USER",
    ratePerUser: 400,
    invoiceMonthYear: isoLocal(twentieth),
    items: [
      {
        name: "Cloud Cost",
        description: "Course5i Cloud Cost",
        totalAmount: "38400.00",
      },
    ],
  };
}

class CreateInvoiceSidebar extends Component {
  constructor(props) {
    super(props);
    this.state = {
      form: getDefaultInvoiceGenerateForm(),
      formError: null,
    };
  }

  componentDidUpdate(prevProps) {
    if (this.props.show && !prevProps.show) {
      this.setState({
        form: getDefaultInvoiceGenerateForm(),
        formError: null,
      });
    }
  }

  onClose = (e) => {
    e.preventDefault();
    this.props.closeActionHandler(e);
  };

  onFieldChange = (field, value) => {
    this.setState((prev) => ({
      form: { ...prev.form, [field]: value },
      formError: null,
    }));
  };

  onItemChange = (index, field, value) => {
    this.setState((prev) => {
      const items = prev.form.items.map((row, i) =>
        i === index ? { ...row, [field]: value } : row
      );
      return { form: { ...prev.form, items }, formError: null };
    });
  };

  addItem = () => {
    this.setState((prev) => ({
      form: {
        ...prev.form,
        items: [
          ...prev.form.items,
          { name: "", description: "", totalAmount: "" },
        ],
      },
      formError: null,
    }));
  };

  removeItem = (index) => {
    this.setState((prev) => ({
      form: {
        ...prev.form,
        items: prev.form.items.filter((_, i) => i !== index),
      },
      formError: null,
    }));
  };

  validate = () => {
    const f = this.state.form;
    if (!f.name || !String(f.name).trim()) {
      return "Name is required.";
    }
    if (!f.invoiceNumber || !String(f.invoiceNumber).trim()) {
      return "Invoice number is required.";
    }
    if (f.createdBy == null || f.createdBy === "") {
      return "Created by (user id) is required.";
    }
    if (f.userTeamId == null || f.userTeamId === "") {
      return "User team id is required.";
    }
    if (!f.items || f.items.length === 0) {
      return "Add at least one additional line item.";
    }
    for (let i = 0; i < f.items.length; i++) {
      const row = f.items[i];
      if (!row.name || !String(row.name).trim()) {
        return `Line item ${i + 1}: name is required.`;
      }
      const amt = parseFloat(row.totalAmount);
      if (Number.isNaN(amt)) {
        return `Line item ${i + 1}: total amount must be a number.`;
      }
    }
    return null;
  };

  handleSave = () => {
    const err = this.validate();
    if (err) {
      this.setState({ formError: err });
      return;
    }
    const f = this.state.form;
    const payload = {
      createdBy: Number(f.createdBy),
      userTeamId: Number(f.userTeamId),
      name: f.name.trim(),
      invoiceNumber: f.invoiceNumber.trim(),
      description: (f.description || "").trim(),
      status: f.status,
      invoiceDateTime: f.invoiceDateTime,
      type: f.type,
      ratePerUser: Number(f.ratePerUser),
      invoiceMonthYear: f.invoiceMonthYear,
      additionalItems: {
        items: f.items.map((row) => ({
          name: row.name.trim(),
          description: (row.description || "").trim(),
          totalAmount: parseFloat(row.totalAmount),
        })),
      },
    };
    this.props.handleSubmit(payload);
  };

  render() {
    const { form, formError } = this.state;
    const statusOptions = [
      "DRAFT",
      "PENDING",
      "APPROVED",
      "PAID",
      "CLOSED",
    ];

    return (
      <div
        id="createinvoicesidebar"
        className={`right_sidebar create_project_right_sidebar ${
          this.props.show ? "open" : ""
        }`}
      >
        <div className="justify-content-between flex-column d-flex h-100vh">
          <div className="card-header py-0 border-bottom">
            <h3 className="card-title">Generate invoice</h3>
            <div className="card-options">
              <button
                type="button"
                onClick={this.onClose}
                className="link p-2 create-project-close-link float-right"
              >
                <i className="fa fa-close" />
              </button>
            </div>
          </div>
          {this.props.show && (
            <div className="card-body pl-3 pr-3 overflow-auto flex-grow-1">
              {formError && (
                <div className="alert alert-warning py-2 mb-3">{formError}</div>
              )}
              <div className="row">
                <div className="col-md-6 mb-2">
                  <label className="form-label">Name</label>
                  <input
                    type="text"
                    className="form-control form-control-sm"
                    value={form.name}
                    onChange={(e) => this.onFieldChange("name", e.target.value)}
                  />
                </div>
                <div className="col-md-6 mb-2">
                  <label className="form-label">Invoice number</label>
                  <input
                    type="text"
                    className="form-control form-control-sm"
                    value={form.invoiceNumber}
                    onChange={(e) =>
                      this.onFieldChange("invoiceNumber", e.target.value)
                    }
                  />
                </div>
                <div className="col-12 mb-2">
                  <label className="form-label">Description</label>
                  <textarea
                    className="form-control form-control-sm"
                    rows={2}
                    value={form.description}
                    onChange={(e) =>
                      this.onFieldChange("description", e.target.value)
                    }
                  />
                </div>
                <div className="col-md-4 mb-2">
                  <label className="form-label">Status</label>
                  <select
                    className="form-control form-control-sm"
                    value={form.status}
                    onChange={(e) =>
                      this.onFieldChange("status", e.target.value)
                    }
                  >
                    {statusOptions.map((s) => (
                      <option key={s} value={s}>
                        {s}
                      </option>
                    ))}
                  </select>
                </div>
                <div className="col-md-4 mb-2">
                  <label className="form-label">Type</label>
                  <input
                    type="text"
                    className="form-control form-control-sm"
                    value={form.type}
                    onChange={(e) => this.onFieldChange("type", e.target.value)}
                  />
                </div>
                <div className="col-md-4 mb-2">
                  <label className="form-label">Rate per user</label>
                  <input
                    type="number"
                    className="form-control form-control-sm"
                    value={form.ratePerUser}
                    onChange={(e) =>
                      this.onFieldChange("ratePerUser", e.target.value)
                    }
                  />
                </div>
                <div className="col-md-6 mb-2">
                  <label className="form-label">Invoice date / time</label>
                  <input
                    type="text"
                    className="form-control form-control-sm"
                    placeholder="YYYY-MM-DDTHH:mm:ss"
                    value={form.invoiceDateTime}
                    onChange={(e) =>
                      this.onFieldChange("invoiceDateTime", e.target.value)
                    }
                  />
                </div>
                <div className="col-md-6 mb-2">
                  <label className="form-label">Invoice month-year</label>
                  <input
                    type="text"
                    className="form-control form-control-sm"
                    placeholder="YYYY-MM-DDTHH:mm:ss"
                    value={form.invoiceMonthYear}
                    onChange={(e) =>
                      this.onFieldChange("invoiceMonthYear", e.target.value)
                    }
                  />
                </div>
                <div className="col-md-6 mb-2">
                  <label className="form-label">Created by (user id)</label>
                  <input
                    type="number"
                    className="form-control form-control-sm"
                    value={form.createdBy != null ? form.createdBy : ""}
                    onChange={(e) =>
                      this.onFieldChange("createdBy", e.target.value)
                    }
                  />
                </div>
                <div className="col-md-6 mb-2">
                  <label className="form-label">User team id</label>
                  <input
                    type="number"
                    className="form-control form-control-sm"
                    value={form.userTeamId != null ? form.userTeamId : ""}
                    onChange={(e) =>
                      this.onFieldChange("userTeamId", e.target.value)
                    }
                  />
                </div>
              </div>

              <div className="d-flex justify-content-between align-items-center mt-3 mb-2">
                <h4 className="mb-0 fsize14 fweight600">Additional items</h4>
                <button
                  type="button"
                  className="btn btn-outline-primary btn-sm"
                  onClick={this.addItem}
                >
                  Add item
                </button>
              </div>
              <div className="table-responsive">
                <table className="table table-sm table-bordered mb-0">
                  <thead>
                    <tr>
                      <th>Name</th>
                      <th>Description</th>
                      <th style={{ minWidth: "6rem" }}>Total amount</th>
                      <th style={{ width: "2.5rem" }} />
                    </tr>
                  </thead>
                  <tbody>
                    {form.items.map((row, index) => (
                      <tr key={index}>
                        <td>
                          <input
                            type="text"
                            className="form-control form-control-sm"
                            value={row.name}
                            onChange={(e) =>
                              this.onItemChange(index, "name", e.target.value)
                            }
                          />
                        </td>
                        <td>
                          <input
                            type="text"
                            className="form-control form-control-sm"
                            value={row.description}
                            onChange={(e) =>
                              this.onItemChange(
                                index,
                                "description",
                                e.target.value
                              )
                            }
                          />
                        </td>
                        <td>
                          <input
                            type="text"
                            className="form-control form-control-sm"
                            value={row.totalAmount}
                            onChange={(e) =>
                              this.onItemChange(
                                index,
                                "totalAmount",
                                e.target.value
                              )
                            }
                          />
                        </td>
                        <td className="text-center">
                          <button
                            type="button"
                            className="btn btn-link btn-sm text-danger p-0"
                            title="Remove row"
                            disabled={form.items.length <= 1}
                            onClick={() => this.removeItem(index)}
                          >
                            <i className="fa fa-trash-o" />
                          </button>
                        </td>
                      </tr>
                    ))}
                  </tbody>
                </table>
              </div>
            </div>
          )}
          {this.props.show && (
            <div className="card-footer py-2 border-top">
              <LoadingButton
                variant="primary"
                size="sm"
                isLoading={this.props.isProcessing}
                loadingText="Saving..."
                onClick={this.handleSave}
              >
                Save invoice
              </LoadingButton>
              <button
                type="button"
                className="btn btn-default btn-sm ml-2"
                disabled={this.props.isProcessing}
                onClick={this.onClose}
              >
                Cancel
              </button>
            </div>
          )}
        </div>
      </div>
    );
  }
}

export default CreateInvoiceSidebar;
