import React, { PureComponent } from "react";
import Skeleton, { SkeletonTheme } from "react-loading-skeleton";
import "./NotesStickyBoard.css";

function tiltDeg(noteId) {
  const n = Number(noteId) || 0;
  const steps = [-1.5, 1.2, -0.8, 1.6, 0.5];
  return steps[Math.abs(n) % steps.length];
}

class NotesStickyBoard extends PureComponent {
  render() {
    const { items, isLoading, permission, formatWhen, onEdit, onToggleComplete, onDelete } = this.props;

    if (isLoading) {
      return (
        <div className="notes-sticky-board notes-sticky-board__skeleton">
          <div className="row">
            {[0, 1, 2, 3, 4, 5].map((i) => (
              <div className="col-md-6 col-lg-4 col-xl-3 mb-4" key={i}>
                <SkeletonTheme color="#fef9c3" highlightColor="#fef08a">
                  <Skeleton height={200} />
                </SkeletonTheme>
              </div>
            ))}
          </div>
        </div>
      );
    }

    return (
      <div className="notes-sticky-board py-2">
        <div className="row">
          {items.map((note) => {
            const done = note.status === "COMPLETED";
            return (
              <div className="col-md-6 col-lg-4 col-xl-3 mb-4 notes-sticky-card-wrap" key={note.id}>
                <div
                  className={`notes-sticky-card ${done ? "notes-sticky-card--done" : ""}`}
                  style={{ transform: `rotate(${tiltDeg(note.id)}deg)` }}
                >
                  <span className="notes-sticky-card__pin" aria-hidden="true" />
                  <div className="notes-sticky-card__complete">
                    <button
                      type="button"
                      className="link"
                      title={done ? "Mark as open" : "Mark complete"}
                      disabled={!permission.editEnabled}
                      onClick={() => onToggleComplete(note)}
                    >
                      <i
                        className={
                          done ? "fa fa-check-square-o text-success" : "fa fa-square-o text-muted"
                        }
                      />
                    </button>
                  </div>
                  {permission.editEnabled ? (
                    <button
                      type="button"
                      className="link notes-sticky-card__title text-left w-100 p-0"
                      onClick={() => onEdit(note)}
                    >
                      {note.name || "Untitled"}
                    </button>
                  ) : (
                    <h4 className="notes-sticky-card__title">{note.name || "Untitled"}</h4>
                  )}
                  {note.description ? (
                    <p className="notes-sticky-card__body">{note.description}</p>
                  ) : (
                    <p className="notes-sticky-card__body text-muted font-italic">No description</p>
                  )}
                  <div className="notes-sticky-card__meta">
                    <span title="When">{formatWhen(note.noteDateTime)}</span>
                    <span className="d-flex align-items-center notes-sticky-card__actions">
                      {note.remindMe ? <i className="fe fe-bell text-primary mr-1" title="Reminder" /> : null}
                      {permission.editEnabled && (
                        <button type="button" className="link" title="Edit" onClick={() => onEdit(note)}>
                          <i className="fa fa-edit" />
                        </button>
                      )}
                      {permission.removeEnabled && (
                        <button type="button" className="link" title="Delete" onClick={() => onDelete(note)}>
                          <i className="fa fa-trash" />
                        </button>
                      )}
                    </span>
                  </div>
                </div>
              </div>
            );
          })}
        </div>
      </div>
    );
  }
}

export default NotesStickyBoard;
