
import { axiosUtils } from '../_helpers';
import urlConfig from 'url.config'

export const taskService = {
    getAllTasks,
    getAllRecurrableTasks,
    getTaskInfo,
    createTask,
    updateTask,
    updateTaskStatus,
    activateTask,
    removeTask,
    deleteTask,
    listNotes,
    createNote,
    updateNote,
    updateNoteStatus,
    removeNote,
};

async function getAllTasks(request) {
    return await axiosUtils.get(urlConfig.TASK_GET_ALL + `/${request.projectId}`);
}

async function getAllRecurrableTasks(request) {
    return await axiosUtils.get(urlConfig.TASK_RECURRABLE_GET_ALL + `/${request.projectId}`);
}
async function getTaskInfo(taskId) {
    return await axiosUtils.get(urlConfig.TASK_GET_INFO + `/${taskId}`);
}

async function createTask(taskRequest) {
    return await axiosUtils.post(urlConfig.TASK_CREATE, taskRequest);
}

async function updateTask(taskRequest) {
    return await axiosUtils.put(urlConfig.TASK_UPDATE, taskRequest);
}
async function updateTaskStatus(taskId, status) {
    return await axiosUtils.put(urlConfig.TASK_UPDATE + `/status/${taskId}/${status}`);
}

async function activateTask(taskId, isActive) {
    return await axiosUtils.put(urlConfig.TASK_ACTIVATE + `/${taskId}/${isActive}`);
}

async function deleteTask(taskId, isDelete) {
    return await axiosUtils.remove(urlConfig.TASK_DELETE + `/${taskId}/${isDelete}`);
}

async function removeTask(taskId) {
    return await axiosUtils.remove(urlConfig.TASK_REMOVE + `/${taskId}`);
}

/**
 * @param {{
 *   employeeId: number,
 *   currentEmployeeId?: number,
 *   startDate: string,
 *   endDate: string
 * }} params
 * Path `employeeId` = whose notes to load; query `employeeId` = current user (when provided).
 */
async function listNotes(params) {
    // Query must stay unencoded (literal colons) for Spring @RequestParam LocalDateTime parsing.
    let q = `startDate=${params.startDate}&endDate=${params.endDate}`;
    if (params.currentEmployeeId != null && params.currentEmployeeId !== "") {
        q += `&employeeId=${params.currentEmployeeId}`;
    }
    return await axiosUtils.get(`${urlConfig.TASK_NOTES_PATH}/${params.employeeId}?${q}`);
}

async function createNote(notesRequest) {
    return await axiosUtils.post(urlConfig.TASK_NOTES_PATH, notesRequest);
}

async function updateNote(notesRequest) {
    return await axiosUtils.put(urlConfig.TASK_NOTES_PATH, notesRequest);
}

async function updateNoteStatus(noteId, status) {
    return await axiosUtils.put(`${urlConfig.TASK_NOTES_PATH}/${noteId}/${status}`, {});
}

async function removeNote(noteId) {
    return await axiosUtils.remove(`${urlConfig.TASK_NOTES_PATH}/${noteId}`);
}
