const DIV_BAR_COLORS = ["bg-azure", "bg-green", "bg-orange", "bg-indigo", "bg-pink"];

function teamLabel(allTeams, userTeamId) {
  const t =
    allTeams &&
    allTeams.find((x) => String(x.id) === String(userTeamId) || x.id === userTeamId);
  return (t && t.name) || `Team ${userTeamId || "—"}`;
}

function countByTeam(activeEmployees, allTeams) {
  const map = {};
  activeEmployees.forEach((e) => {
    const key = e.userTeamId != null ? String(e.userTeamId) : "_none";
    map[key] = (map[key] || 0) + 1;
  });
  const entries = Object.entries(map).sort((a, b) => b[1] - a[1]);
  return entries.map(([id, count]) => ({
    id: id === "_none" ? null : id,
    label: id === "_none" ? "Unassigned" : teamLabel(allTeams, id),
    count,
  }));
}

function parseJoinMoment(val) {
  if (!val) return null;
  let m = moment(val, moment.ISO_8601, true);
  if (m.isValid()) return m;
  m = moment(val, dateUtils.CLIENT_DATE_FORMAT, true);
  if (m.isValid()) return m;
  m = moment(val);
  return m.isValid() ? m : null;
}

function buildTeamwiseStackSeries(activeEmployees, allTeams) {
  if (!activeEmployees.length) {
    return {
      categories: ["—"],
      series: [{ name: "Employees", data: [0] }],
      subtitle: "No employees loaded for this view",
    };
  }

  const months = [];
  for (let i = 5; i >= 0; i -= 1) {
    const mm = moment().subtract(i, "months").startOf("month");
    months.push({
      label: mm.format("MMM YY"),
      y: mm.year(),
      m: mm.month(),
    });
  }

  const ranked = countByTeam(activeEmployees, allTeams);
  const top = ranked.slice(0, 4).map((r) => r.id);
  const topSet = new Set(top.map((id) => (id != null ? String(id) : "")));

  function bucketTeam(uid) {
    const k = uid != null ? String(uid) : "";
    if (topSet.has(k)) return k;
    return "__other__";
  }

  const seriesKeys = [...top.filter((id) => id != null), "__other__"];
  const seriesNames = seriesKeys.map((key) =>
    key === "__other__"
      ? "Other"
      : teamLabel(allTeams, key)
  );

  let hireTotal = 0;
  const series = seriesKeys.map((teamKey, idx) => ({
    name: seriesNames[idx],
    data: months.map(({ y, m }) => {
      const n = activeEmployees.filter((e) => {
        const dj = parseJoinMoment(e.dateOfJoin);
        if (!dj) return false;
        return dj.year() === y && dj.month() === m && bucketTeam(e.userTeamId) === teamKey;
      }).length;
      hireTotal += n;
      return n;
    }),
  }));

  const categories = months.map((x) => x.label);

  if (hireTotal === 0) {
    const head = ranked.slice(0, 6);
    const sumOther = ranked.slice(6).reduce((s, r) => s + r.count, 0);
    const headSeries = head.map((r) => ({
      name: r.label,
      data: [r.count],
    }));
    let stackSeries =
      sumOther > 0 ? [...headSeries, { name: "Other", data: [sumOther] }] : headSeries;
    if (!stackSeries.length) {
      stackSeries = [{ name: "Employees", data: [0] }];
    }
    return {
      categories: ["Active employees"],
      series: stackSeries,
      subtitle: "Headcount by team (no hires in the last 6 months)",
    };
  }

  return {
    categories,
    series,
    subtitle: "New hires by team (join date in month)",
  };
}

function buildDonutLocation(activeEmployees, allTeams) {
  if (!activeEmployees.length) {
    return { labels: ["No employees"], series: [1] };
  }

  const ranked = countByTeam(activeEmployees, allTeams).slice(0, 6);
  const taken = ranked.reduce((s, r) => s + r.count, 0);
  const total = activeEmployees.length;
  const other = Math.max(0, total - taken);
  const labels = ranked.map((r) => r.label);
  const series = ranked.map((r) => r.count);
  if (other > 0) {
    labels.push("Other teams");
    series.push(other);
  }
  return { labels, series };
}

function buildPieEmpTypes(activeEmployees) {
  if (!activeEmployees.length) {
    return { labels: ["—"], series: [1] };
  }

  const types = {};
  activeEmployees.forEach((e) => {
    const t = e.empType || "Other";
    types[t] = (types[t] || 0) + 1;
  });
  const entries = Object.entries(types).sort((a, b) => b[1] - a[1]);
  return {
    labels: entries.map(([k]) => k),
    series: entries.map(([, v]) => v),
  };
}

function buildGenderByTeam(activeEmployees, allTeams) {
  if (!activeEmployees.length) {
    return {
      series: [
        { name: "Male", data: [0] },
        { name: "Female", data: [0] },
        { name: "Other / undeclared", data: [0] },
      ],
      categories: ["—"],
    };
  }

  const ranked = countByTeam(activeEmployees, allTeams).slice(0, 10);
  const matchesTeam = (e, teamId) => {
    const eu = e.userTeamId;
    if (teamId == null || teamId === "") return eu == null || eu === "";
    return String(eu) === String(teamId);
  };

  const male = ranked.map((r) =>
    activeEmployees.filter(
      (e) => matchesTeam(e, r.id) && (e.gender || "").toLowerCase() === "male"
    ).length
  );
  const female = ranked.map((r) =>
    activeEmployees.filter(
      (e) => matchesTeam(e, r.id) && (e.gender || "").toLowerCase() === "female"
    ).length
  );
  const other = ranked.map((r, i) => {
    const m = male[i];
    const f = female[i];
    return Math.max(0, r.count - m - f);
  });
  return {
    series: [
      { name: "Male", data: male },
      { name: "Female", data: female },
      { name: "Other / undeclared", data: other },
    ],
    categories: ranked.map((r) => r.label),
  };
}

function buildDivisionDesignations(activeEmployees, limit = 5) {
  const map = {};
  activeEmployees.forEach((e) => {
    const d = (e.designation && String(e.designation).trim()) || "Other";
    map[d] = (map[d] || 0) + 1;
  });
  const entries = Object.entries(map).sort((a, b) => b[1] - a[1]).slice(0, limit);
  const total = activeEmployees.length || 1;
  return entries.map(([name, count]) => ({
    name,
    count,
    pct: Math.round((count / total) * 100),
  }));
}

