function dashboardEmployeeSource(state) {
  const { allEmployees, items } = state.employees;
  if (allEmployees !== undefined) {
    return allEmployees;
  }
  return items || [];
}

const mapStateToProps = (state) => {
  const employeeList = dashboardEmployeeSource(state);
  return {
    employeesItems: employeeList,
    loading: state.employees.loading,
    filteredEmployees: commonUtils.filterEmployees(
      employeeList,
      state.employees.filterOptions || DEFAULT_FILTER_OPTIONS
    ),
    userTeamsProp: state.employees.userTeams,
    allTeams: state.appconfig.allTeams,
  };
};

const mapDispatchToProps = {
  //getTeamsEmployees: employeeActions.getTeamsEmployeesPage,
  getAllEmployees: employeeActions.getAllEmployees,
};

