import React, { PureComponent } from "react";
import Skeleton from "react-loading-skeleton";
import NoteInfoLine from "./NoteInfoLine";

class NotesListTable extends PureComponent {
  render() {
    const { items, isLoading, permission, formatWhen, onToggleComplete, onEdit, onDelete } = this.props;

    return (
      <div className="table-responsive">
        <table className="table table_custom table-nowrap table-vcenter table-borderless position-relative mb-0">
          <thead>
            <tr>
              <th />
              <th>#</th>
              <th>When</th>
              <th className="w-250">Title</th>
              <th>Status</th>
              <th className="text-center">Remind</th>
              <th className="text-center">Action</th>
            </tr>
          </thead>
          <tbody>
            {isLoading && (
              <tr>
                <td colSpan={7}>
                  <Skeleton count={6} height={40} />
                </td>
              </tr>
            )}
            {!isLoading &&
              items.map((note) => (
                <NoteInfoLine
                  key={note.id}
                  item={note}
                  permission={permission}
                  formatWhen={formatWhen}
                  onToggleComplete={onToggleComplete}
                  onEdit={onEdit}
                  onDelete={onDelete}
                />
              ))}
          </tbody>
        </table>
      </div>
    );
  }
}

export default NotesListTable;
