import React, { Component } from "react";
import { NavLink } from "react-router-dom";
import { workItemConstants } from "_constants";
import { accessUtils } from "_helpers";
import { store } from "_helpers";
import EmployeeImage from "./fragments/EmployeeImage";
import classNames from "classnames/bind";
import { employeeConstants } from "_constants";

class PageLeftMenubar extends Component {
  constructor() {
    super()
    this.state = {
      permission: accessUtils.getMenuAccessControl()
    };
  }
  toggleTodayActivitySidebar = () => {
    store.dispatch({ type: workItemConstants.SHOW_TODAYS_ACTIVITY_WINDOW })
  }
  toggleUserDivSidebar = () => {
    store.dispatch({ type: employeeConstants.TOGGLE_USER_DIV_WINDOW })
  }
  isDisabled = (module, linkName) => {
    return this.state.permission && this.state.permission[module] && this.state.permission[module][linkName] === false;
  }
  render() {
    return (
      <div id="header_top" className="header_top no-print">
        <div className="container">
          <div className="hleft">
            {this.isDisabled("projectModules", "dashboardEnabled") &&
              <NavLink to={"/project/dashboard"} className="header-brand" data-ga-action="nav_dashboard" data-ga-category="navigation" data-ga-label="Dashboard">
                <img className="iconrotate" src="/favicon.ico" style={{ width: 30 + 'px' }}></img>
                <img alt="fav icon" src="/assets/images/custom/c5i-logo.png" style={{ width: 45 + 'px', display: 'block' }}></img>
              </NavLink>
            }
            {!this.isDisabled("projectModules", "dashboardEnabled") &&
              <button type="button" className="link header-brand" data-ga-action="nav_brand" data-ga-category="navigation" data-ga-label="Brand">
                <img className="iconrotate" src="/favicon.ico" style={{ width: 30 + 'px' }}></img>
                <img alt="fav icon" src="/assets/images/custom/c5i-logo.png" style={{ width: 45 + 'px', display: 'block' }}></img>
              </button>
            }
           
            <div className="dropdown">
              <NavLink to={"/project/search"} className={classNames("nav-link icon", { "disabled colorlightgray": this.isDisabled("projectModules", "searchEnabled") })} activeClassName="active" data-ga-action="nav_search" data-ga-category="navigation" data-ga-label="Search"> <i className="fa fa-search" /></NavLink>
              <NavLink to={"/project/taskboard"} className={classNames("nav-link icon", { "disabled colorlightgray": this.isDisabled("projectModules", "taskboardEnabled") })} activeClassName="active" data-ga-action="nav_taskboard" data-ga-category="navigation" data-ga-label="Taskboard"> <i className="fa fa-tasks" /></NavLink>
              <NavLink to={"/project/calendar"} className={classNames("nav-link icon", { "disabled  colorlightgray": this.isDisabled("projectModules", "calendarEnabled") })} activeClassName="active" data-ga-action="nav_calendar" data-ga-category="navigation" data-ga-label="Calendar"> <i className="fa fa-calendar" /></NavLink>
              <NavLink to={"/project/chat"} className={classNames("nav-link icon disabled d-none d-md-inline-flex", { "disabled colorlightgray": this.isDisabled("projectModules", "chatEnabled") })} activeClassName="active" data-ga-action="nav_chat" data-ga-category="navigation" data-ga-label="Chat"> <i className="fa fa-comments-o" /></NavLink>
              <NavLink to={"/project/filemanager"} className={classNames("nav-link icon disabled d-none d-md-inline-flex", { "disabled colorlightgray": this.isDisabled("projectModules", "filemanagerEnabled") })} activeClassName="active" data-ga-action="nav_filemanager" data-ga-category="navigation" data-ga-label="File manager"> <i className="fa fa-folder-o" /></NavLink>

            </div>
          </div>
          <div className="hright">
            <div className="dropdown">
              <button type="button" className="link nav-link icon theme_btn d-none d-md-inline-flex" data-ga-action="nav_themes" data-ga-category="navigation" data-ga-label="Themes"><i className="fa fa-paint-brush" data-toggle="tooltip" data-placement="right" title="Themes" /></button>
              <NavLink to={"/hrms/appconfig"} className={classNames("nav-link icon", { "disabled colorlightgray": this.isDisabled("hrmsModules", "appconfigEnabled") })} activeClassName="active" data-ga-action="nav_appconfig" data-ga-category="navigation" data-ga-label="App config"> <i className="fa fa-cogs" /></NavLink>
              <button type="button" className="link nav-link icon settingbar" data-ga-action="nav_settings" data-ga-category="navigation" data-ga-label="Settings"><i className="fa fa-gear fa-spin" data-toggle="tooltip" data-placement="right" title="Settings" /></button>
              <button type="button" className="link nav-link iconfaq_btn todayactivity" onClick={() => this.toggleTodayActivitySidebar()} data-ga-action="nav_today_activity" data-ga-category="navigation" data-ga-label="Today activity"><i className="fa fa-stack-exchange"></i></button>

              <button type="button" className="link nav-link user_btn" onClick={() => this.toggleUserDivSidebar()} data-ga-action="nav_user_menu" data-ga-category="navigation" data-ga-label="User menu">
                <EmployeeImage employee={this.props.authentication && this.props.authentication.user} classes={"avatar"} />
              </button>
              <button type="button" className="link nav-link icon menu_toggle" data-ga-action="nav_menu_toggle" data-ga-category="navigation" data-ga-label="Menu toggle"><i className="fa fa-align-left" /></button>
            </div>
          </div>
        </div>
      </div>
    );
  }
}

export default PageLeftMenubar;
