import React, { Component } from "react";
import "./PageFooter.css";

class PageFooter extends Component {
    render() {
        const currentYear = new Date().getFullYear();
        
        return (
            <footer className="page-footer-modern">
                <div className="container-fluid">
                    <div className="footer-content-simple">
                        <div className="footer-left">
                            <span className="footer-copyright">
                                © {currentYear} <a href="https://infleca.com" target="_blank" rel="noopener noreferrer" className="footer-link-brand">Infleca Innovation Pvt Ltd</a>
                            </span>
                            <span className="footer-separator">|</span>
                            <a href="/documentation/index.html" className="footer-link" target="_blank" rel="noopener noreferrer">
                                <i className="fa fa-book mr-2"></i>Documentation
                            </a>
                        </div>
                    </div>
                </div>
            </footer>
        );
    }
}

export default PageFooter;